"""Built-in golden test recipes: CPU torch golden + NPU forward + check_*.

Each recipe returns a complete Python test file body (without license header).
"""

from __future__ import annotations

from typing import Any

_FILE_HEADER = '''\
#
# DO NOT EDIT - generated by atb-bindgen
#
# Copyright (c) 2025 Huawei Technologies Co., Ltd.
# This program is free software, you can redistribute it and/or modify it under the terms and conditions of
# CANN Open Software License Agreement Version 2.0 (the "License").
#

'''

_COMMON_IMPORTS = '''\
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch_atb
import unittest
import logging
from torch_atb_test.utils import check_float, check_move, run_perf_test

'''


def _wrap(class_name: str, run_test_body: str, check_note: str = "") -> str:
    return (
        _FILE_HEADER
        + _COMMON_IMPORTS
        + f"\n{check_note}\n"
        + "def run_test():\n"
        + _indent(run_test_body, 4)
        + f"\n\nclass {class_name}(unittest.TestCase):\n"
        + "    def test_forward_golden(self):\n"
        + "        run_test()\n\n"
        + 'if __name__ == "__main__":\n'
        + "    unittest.main()\n"
    )


def _indent(text: str, spaces: int) -> str:
    pad = " " * spaces
    lines = text.splitlines(keepends=True)
    if not lines:
        return text
    # splitlines(keepends=True) may leave last line without newline
    result = []
    for line in lines:
        if line.strip():
            result.append(pad + line)
        else:
            result.append(line)
    return "".join(result)


RECIPES: dict[str, str] = {}

RECIPES["SplitParam"] = _wrap(
    "TestSplitBindgen",
    '''\
print("----------- split bindgen test begin ------------")
split_dim = 0
split_num = 2
input_cpu = torch.randn(6, 6, dtype=torch.float16)
input_npu = input_cpu.npu()
param = torch_atb.SplitParam()
param.split_dim = split_dim
param.split_num = split_num
op = torch_atb.Operation(param)
logging.info(param)

def golden():
    parts = torch.chunk(input_cpu, chunks=split_num, dim=split_dim)
    return torch.stack(parts)

cpu_goldens = golden()
npu_outputs = op.forward([input_npu])
logging.info("npu_outputs: %s", npu_outputs)
assert check_move(npu_outputs, cpu_goldens), "Split golden mismatch"
run_perf_test(op, [input_npu])
print("----------- split bindgen test success ------------")
''',
)

