RECIPES["SoftmaxParam"] = _wrap(
    "TestSoftmaxBindgen",
    '''\
print("----------- softmax bindgen test begin ------------")
axes = [0]
input_cpu = torch.randn(2, 16, 256, dtype=torch.float32)
input_npu = input_cpu.npu()
param = torch_atb.SoftmaxParam()
param.axes = axes
op = torch_atb.Operation(param)
logging.info(param)

def golden():
    dim_num = input_cpu.dim()
    axes_norm = [i % dim_num for i in axes]
    target_shape = input_cpu.shape[axes_norm[0]:axes_norm[-1] + 1]
    flat = input_cpu.flatten(start_dim=axes_norm[0], end_dim=axes_norm[-1])
    out = torch.nn.Softmax(dim=axes_norm[0])(flat)
    return [out.unflatten(axes_norm[0], target_shape)]

cpu_goldens = golden()
npu_outputs = op.forward([input_npu])
assert check_float(npu_outputs, cpu_goldens), "Softmax golden mismatch"
run_perf_test(op, [input_npu])
print("----------- softmax bindgen test success ------------")
''',
)

