# torch_compose recipes
RECIPES["RmsNormParam"] = _wrap(
    "TestRmsNormBindgen",
    '''\
print("----------- rms_norm bindgen test begin ------------")
eps = 1e-5
shape = [8, 8, 8]
gamma_shape = [8]
x_cpu = torch.randn(shape, dtype=torch.float32)
gamma_cpu = torch.randn(gamma_shape, dtype=torch.float32)
x_npu, gamma_npu = x_cpu.npu(), gamma_cpu.npu()
param = torch_atb.RmsNormParam()
param.layer_type = torch_atb.RmsNormParam.RmsNormType.RMS_NORM_NORM
param.norm_param.rstd = True
param.norm_param.epsilon = eps
op = torch_atb.Operation(param)
logging.info(param)

def golden():
    # torch 原生算子拼接：RMSNorm(x, gamma) + rstd
    reduce_dims = list(range(x_cpu.dim() - gamma_cpu.dim(), x_cpu.dim()))
    rstd = torch.rsqrt(x_cpu.pow(2).mean(reduce_dims, keepdim=True) + eps)
    out = x_cpu * rstd * gamma_cpu
    return [out, rstd]

cpu_goldens = golden()
npu_outputs = op.forward([x_npu, gamma_npu])
assert check_float(npu_outputs, cpu_goldens), "RmsNorm golden mismatch"
run_perf_test(op, [x_npu, gamma_npu])
print("----------- rms_norm bindgen test success ------------")
''',
)

RECIPES["IndexAddParam"] = (
    _FILE_HEADER
    + _COMMON_IMPORTS
    + "\n# IndexAdd 为 inplace 算子，与 gather 等 perf 测试同进程会污染 workspace，使用子进程隔离\n"
    + "def run_test():\n"
    + _indent(
        '''\
print("----------- index_add bindgen test begin ------------")
torch.manual_seed(42)
axis = 0
var_cpu = torch.randn(8, 14, dtype=torch.float16)
indices_cpu = torch.arange(5, dtype=torch.int32)
updates_cpu = torch.randn(5, 14, dtype=torch.float16)
alpha_cpu = torch.tensor([1.0], dtype=torch.float16)
var_npu = var_cpu.npu()
indices_npu = indices_cpu.npu()
updates_npu = updates_cpu.npu()
alpha_npu = alpha_cpu.npu()
param = torch_atb.IndexAddParam()
param.index_type = torch_atb.IndexAddParam.IndexType.INDEX_ADD
param.axis = axis
op = torch_atb.Operation(param)
logging.info(param)

def golden():
    out = var_cpu.clone()
    out.index_add_(axis, indices_cpu, updates_cpu, alpha=alpha_cpu.item())
    return [out - var_cpu]

cpu_goldens = golden()
npu_outputs = op.forward([var_npu, indices_npu, updates_npu, alpha_npu])
torch.npu.synchronize()
assert check_float(npu_outputs, cpu_goldens), "IndexAdd golden mismatch"
run_perf_test(op, [var_npu.clone(), indices_npu, updates_npu, alpha_npu])
print("----------- index_add bindgen test success ------------")
''',
        4,
    )
    + "\n\nclass TestIndexAddBindgen(unittest.TestCase):\n"
    + "    def test_forward_golden(self):\n"
    + "        import os\n"
    + "        import subprocess\n"
    + "        import sys\n"
    + "        apitest_root = os.path.abspath(os.path.join(os.path.dirname(__file__), \"..\", \"..\", \"..\"))\n"
    + "        proc = subprocess.run(\n"
    + "            [sys.executable, \"-c\", \"from torch_atb_test.op_test.index_add.index_add_bindgen_test import run_test; run_test()\"],\n"
    + "            cwd=apitest_root,\n"
    + "            env=os.environ.copy(),\n"
    + "        )\n"
    + "        self.assertEqual(proc.returncode, 0)\n\n"
    + 'if __name__ == "__main__":\n'
    + "    unittest.main()\n"
)

