def get_recipe(param_name: str) -> str | None:
    return RECIPES.get(param_name)


def get_manual_stub(param_name: str, op_snake: str) -> str:
    class_name = f"Test{param_name}Manual"
    body = f'''\
print("----------- {op_snake} manual golden test (TODO) ------------")
raise unittest.SkipTest("custom_manual: implement compute_golden() before enabling")
'''
    return _wrap(class_name, body)


def categories_with_recipes() -> set[str]:
    return set(RECIPES.keys())
